'use client';

import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { ethers } from 'ethers';
import { getQuote, getPrice, getReserves } from './pecor';
import { getPoolState, quoteBuy, quoteSell } from './sidiora';

function useFinancialRead<T>(read: () => Promise<T>, enabled: boolean, provider?: ethers.Provider) {
  const [networkGeneration, setNetworkGeneration] = useState(0);
  const identity = useMemo(() => ({}), [read, enabled, networkGeneration]);
  const active = useRef<{ identity: object; generation: number } | null>(null);
  const [result, setResult] = useState<{
    identity: object;
    data: T | null;
    loading: boolean;
    error: string | null;
  }>({ identity, data: null, loading: enabled, error: null });

  const refresh = useCallback(async () => {
    const scope = active.current;
    if (!enabled || !scope || scope.identity !== identity) return;
    const generation = ++scope.generation;
    setResult({ identity, data: null, loading: true, error: null });
    const isCurrent = () => active.current === scope && scope.generation === generation;
    try {
      const data = await read();
      if (isCurrent()) setResult({ identity, data, loading: false, error: null });
    } catch (error) {
      if (isCurrent()) setResult({ identity, data: null, loading: false, error: String(error) });
    }
  }, [identity, read, enabled]);

  useEffect(() => {
    active.current = { identity, generation: 0 };
    if (enabled) void refresh();
    else setResult({ identity, data: null, loading: false, error: null });
    return () => {
      active.current = null;
    };
  }, [identity, enabled, refresh]);

  useEffect(() => {
    if (!provider) return;
    let subscribed = true;
    const onNetwork = (_network: ethers.Network, previous: ethers.Network | null) => {
      if (!subscribed || previous === null) return;
      active.current = null;
      setNetworkGeneration((value) => value + 1);
    };
    const subscription = provider.on('network', onNetwork).catch((error) => {
      if (!subscribed) return;
      active.current = null;
      setResult({ identity, data: null, loading: false, error: String(error) });
    });
    return () => {
      subscribed = false;
      void subscription.then(() => provider.off('network', onNetwork));
    };
  }, [provider, identity]);

  const current =
    result.identity === identity && enabled
      ? result
      : { data: null, loading: enabled, error: null };
  return { data: current.data, loading: current.loading, error: current.error, refresh };
}

interface UseSwapQuoteParams {
  tokenIn: string;
  tokenOut: string;
  amountIn: bigint;
  provider?: ethers.Provider;
}

export function useSwapQuote({ tokenIn, tokenOut, amountIn, provider }: UseSwapQuoteParams) {
  const read = useCallback(
    () => getQuote(tokenIn, tokenOut, amountIn, provider),
    [tokenIn, tokenOut, amountIn, provider]
  );
  const { data, ...status } = useFinancialRead(
    read,
    !!tokenIn && !!tokenOut && amountIn !== 0n,
    provider
  );
  return { quote: data, ...status };
}

export function useTokenPrice(tokenAddress: string, provider?: ethers.Provider) {
  const read = useCallback(() => getPrice(tokenAddress, provider), [tokenAddress, provider]);
  const { data, ...status } = useFinancialRead(read, !!tokenAddress, provider);
  return { price: data?.price ?? null, stale: data?.stale ?? false, ...status };
}

export function useVaultReserves(tokenAddress: string, provider?: ethers.Provider) {
  const read = useCallback(() => getReserves(tokenAddress, provider), [tokenAddress, provider]);
  const { data, ...status } = useFinancialRead(read, !!tokenAddress, provider);
  return { reserves: data, ...status };
}

export function useSidioraPool(poolAddress: string, provider?: ethers.Provider) {
  const read = useCallback(() => getPoolState(poolAddress, provider), [poolAddress, provider]);
  const { data, ...status } = useFinancialRead(read, !!poolAddress, provider);
  return { state: data, ...status };
}

